### 🛠️ Production Implementation & Technical Verification

1. **Root Cause Analysis & Architectural Design**:

`postUser` currently passes `req.body` straight to `createUser`, and the service spreads it into the persisted record. This permits malformed identities, mass-assignment fields, prototype-pollution keys, and cleartext credential fields.

The patch introduces a strict Zod boundary schema at the controller layer. It:

- Requires a normalized valid email and a trimmed `fullName` of 2–100 characters.
- Allows only optional `bio`, `role`, and transient `password`.
- Rejects all unknown keys with a consistent `400` envelope.
- Removes `password` before calling the service.
- Adds service-side credential stripping as defense in depth, including direct service callers.

2. **Production-Grade Implementation Source Code**:

### Production Source (`apps/api/src/schemas/userSchema.js`)

```js
import { z } from "zod";

export const createUserSchema = z
  .object({
    email: z
      .string()
      .trim()
      .email("email must be a valid email address")
      .max(254, "email must not exceed 254 characters")
      .transform((email) => email.toLowerCase()),

    fullName: z
      .string()
      .trim()
      .min(2, "fullName must contain at least 2 characters")
      .max(100, "fullName must not exceed 100 characters"),

    bio: z
      .string()
      .trim()
      .max(500, "bio must not exceed 500 characters")
      .optional(),

    role: z.enum(["client", "freelancer"]).default("client"),

    // Accepted only so legacy/public registration clients do not persist
    // cleartext credentials. It is explicitly removed by the controller.
    password: z.string().max(4096, "password must not exceed 4096 characters").optional()
  })
  .strict("Unknown properties are not allowed");
```

### Production Source (`apps/api/src/controllers/userController.js`)

```js
import { fail, ok } from "../utils/response.js";
import { createUser, listUsers } from "../services/userService.js";
import { createUserSchema } from "../schemas/userSchema.js";

export async function getUsers(req, res) {
  return ok(res, await listUsers());
}

export async function postUser(req, res) {
  const parsed = createUserSchema.safeParse(req.body);

  if (!parsed.success) {
    return fail(res, "Invalid user creation payload", 400);
  }

  const { password, ...userInput } = parsed.data;
  const user = await createUser(userInput);

  return ok(res, user, 201);
}
```

### Production Source (`apps/api/src/services/userService.js`)

```js
const users = [];

const SENSITIVE_USER_FIELDS = new Set([
  "password",
  "passwordHash",
  "password_hash"
]);

function removeSensitiveFields(payload) {
  return Object.fromEntries(
    Object.entries(payload).filter(([key]) => !SENSITIVE_USER_FIELDS.has(key))
  );
}

export async function listUsers() {
  return users;
}

export async function createUser(payload) {
  const sanitizedPayload = removeSensitiveFields(payload);

  const user = {
    id: `usr_${Date.now()}`,
    ...sanitizedPayload
  };

  users.push(user);

  return user;
}
```

3. **Comprehensive Unit Test Suite & Verification Harness**:

### Test Suite (`apps/api/src/tests/userValidation.test.js`)

```js
import assert from "node:assert/strict";
import test from "node:test";
import { createApp } from "../app.js";
import { listUsers } from "../services/userService.js";

async function withServer(run) {
  const app = createApp();
  const server = app.listen(0);

  await new Promise((resolve, reject) => {
    server.once("listening", resolve);
    server.once("error", reject);
  });

  try {
    const { port } = server.address();
    await run(`http://127.0.0.1:${port}`);
  } finally {
    await new Promise((resolve, reject) => {
      server.close((error) => (error ? reject(error) : resolve()));
    });
  }
}

async function postUser(baseUrl, body) {
  const response = await fetch(`${baseUrl}/api/users`, {
    method: "POST",
    headers: {
      "content-type": "application/json"
    },
    body: JSON.stringify(body)
  });

  return {
    response,
    payload: await response.json()
  };
}

test("POST /api/users accepts and normalizes a valid payload", async () => {
  await withServer(async (baseUrl) => {
    const { response, payload } = await postUser(baseUrl, {
      email: "  ARCHITECT@EXAMPLE.COM ",
      fullName: " Kunal Das ",
      bio: "Systems architect",
      role: "freelancer"
    });

    assert.equal(response.status, 201);
    assert.equal(payload.success, true);
    assert.equal(payload.data.email, "architect@example.com");
    assert.equal(payload.data.fullName, "Kunal Das");
    assert.equal(payload.data.bio, "Systems architect");
    assert.equal(payload.data.role, "freelancer");
    assert.match(payload.data.id, /^usr_\d+$/);
  });
});

test("POST /api/users rejects an invalid email", async () => {
  await withServer(async (baseUrl) => {
    const { response, payload } = await postUser(baseUrl, {
      email: "not-an-email",
      fullName: "Kunal Das"
    });

    assert.equal(response.status, 400);
    assert.deepEqual(payload, {
      success: false,
      message: "Invalid user creation payload"
    });
  });
});

test("POST /api/users rejects a missing fullName", async () => {
  await withServer(async (baseUrl) => {
    const { response, payload } = await postUser(baseUrl, {
      email: "kunal@example.com"
    });

    assert.equal(response.status, 400);
    assert.deepEqual(payload, {
      success: false,
      message: "Invalid user creation payload"
    });
  });
});

test("POST /api/users rejects unknown and prototype-pollution properties", async () => {
  await withServer(async (baseUrl) => {
    const { response, payload } = await postUser(baseUrl, {
      email: "kunal@example.com",
      fullName: "Kunal Das",
      isAdmin: true,
      __proto__: {
        polluted: true
      }
    });

    assert.equal(response.status, 400);
    assert.deepEqual(payload, {
      success: false,
      message: "Invalid user creation payload"
    });
    assert.equal({}.polluted, undefined);
  });
});

test("POST /api/users never returns or persists an unhashed password", async () => {
  await withServer(async (baseUrl) => {
    const { response, payload } = await postUser(baseUrl, {
      email: "secure@example.com",
      fullName: "Secure User",
      password: "cleartext-password-must-not-persist"
    });

    assert.equal(response.status, 201);
    assert.equal(payload.success, true);
    assert.equal("password" in payload.data, false);
    assert.equal("passwordHash" in payload.data, false);
    assert.equal("password_hash" in payload.data, false);

    const persistedUser = (await listUsers()).find(
      (user) => user.id === payload.data.id
    );

    assert.ok(persistedUser);
    assert.equal("password" in persistedUser, false);
    assert.equal("passwordHash" in persistedUser, false);
    assert.equal("password_hash" in persistedUser, false);
  });
});
```

